import{_ as o,C as s,o as n,c as r,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const b=JSON.parse('{"title":"Follow a Playwright run","description":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window.","frontmatter":{"title":"Follow a Playwright run","description":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/watch-a-run.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/watch-a-run.html"}],["meta",{"property":"og:title","content":"Follow a Playwright run | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Follow a Playwright run while it goes, in the same words in every Piwi tool: its number and page on the instance, where a test stopped and why, and how far it is in the editors and the Runs window."}]]},"headers":[],"relativePath":"features/watch-a-run.md","filePath":"features/watch-a-run.md","lastUpdated":1795107447000}'),l={name:"features/watch-a-run.md"};function p(u,e,w,c,g,f){const a=s("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"follow-a-run",tabindex:"-1"},[i("Follow a run "),t("a",{class:"header-anchor",href:"#follow-a-run","aria-label":'Permalink to "Follow a run"'},"​")],-1)),h(a,{reporter:""}),e[1]||(e[1]=d('<p>This page follows a run while it goes, in the same words in every tool: its number and page on the instance, how far it is, where a test stopped and why, and when a failing test is held. To see a test&#39;s page: <a href="./watch-running-test.html">Watch a local test</a> in your tools, <a href="./live-view.html">Live view of a run</a> on the team instance.</p><h2 id="the-run-s-number-and-page" tabindex="-1">The run&#39;s number and page <a class="header-anchor" href="#the-run-s-number-and-page" aria-label="Permalink to &quot;The run&#39;s number and page&quot;">​</a></h2><p>A run has one number on the instance it reports to, <code>#78</code>, and one page. The reporter learns the number as the run starts: from the global setup that registered it, else as its stream to the instance opens. It prints the page once, and tells it to the editor or the desktop app that follows the run. The page is under the instance&#39;s public address when the instance sets <code>PIWI_SITE_URL</code>, else under the address the reporter reached it at. A tool links it only on this machine or under an instance it connects to itself: in an editor, the instance of a Playwright config of the window; in the desktop app, the team instance whose run requests it takes. A page elsewhere, which the test&#39;s own code could name, is not shown, and the run reads as one with no number.</p><table tabindex="0"><thead><tr><th>Where</th><th>What it shows</th></tr></thead><tbody><tr><td>The terminal</td><td><code>[Piwi Dashboard] View live progress: https://piwi.example.com/test-runs/78</code>, once, at its start</td></tr><tr><td>VS Code</td><td>The run-control item: <code>#78 · 3 of 9</code>, its tooltip <strong>Open run #78</strong>; while your run goes, <strong>Open run #78 (running)</strong> first in the status bar item&#39;s tooltip; <strong>Piwi: Open the page of a run of this window</strong> and <strong>Piwi: Open the branch&#39;s run in progress</strong> in the palette</td></tr><tr><td>JetBrains IDEs</td><td>The status bar item: <code>Piwi: run #78 · 3 of 9</code>, kept beside a stop or a share; <strong>Open run #78</strong> in its menu; <strong>Open run #78 (running)</strong> in place of <strong>Open the latest run</strong> while it goes</td></tr><tr><td>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></td><td><strong>Run #78</strong>, <strong>Open</strong> and <strong>Copy link</strong> on the run&#39;s card, while it runs and after it ended, with its progress and how it ended</td></tr><tr><td>The desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a></td><td><strong>Run #78 · Open</strong> under each run of its hub, a run a team instance asked for included, whose page opens in the browser; <strong>Open run #78</strong> on a run the app&#39;s own server holds</td></tr><tr><td><strong>Debug in my editor</strong></td><td>Once the editor runs the test: &quot;Following run #81 in VS Code · Open&quot; beside the button</td></tr></tbody></table><p>A run that reports to no instance, or with <code>streaming: false</code> and no global setup, has no number until its results are sent.</p><h2 id="how-far-it-is" tabindex="-1">How far it is <a class="header-anchor" href="#how-far-it-is" aria-label="Permalink to &quot;How far it is&quot;">​</a></h2><p>The reporter&#39;s own process tells the editor or the desktop app how many tests the run holds, how many ended and how, and how the run ended with its first failure. The editors&#39; status bars and the Runs window count it the same way: each test once, by its last attempt. The desktop tray counts as the run&#39;s own process does (<a href="./local-runs-tray.html#each-run">Local runs tray</a>).</p><p>On the dashboard, Home&#39;s <strong>Recent activity</strong>, a project&#39;s runs list and the <strong>Projects</strong> page show a running run with the count bar and how many results are in: <code>120 of 400 · 2 failed</code>. Its row moves on by itself as results reach the instance, at most every 2 seconds, without the page reading the list again. Until the run ends these count each result as the reporter sends it, a retry again; the run&#39;s page counts each test once.</p><p>The status bar item&#39;s tooltip also says what each worker runs now (<code>Worker 2 · cart › adds a mug · stopped</code>). In VS Code, the Testing view&#39;s test run of your run writes in its output each test a worker starts, each stop and why, with the line it stands at, and each stop answered.</p><p>A run in progress that is not yours, a CI run or a teammate&#39;s, shows read-only: <a href="./editor-ci-runs.html">A CI run of your branch</a>.</p><h2 id="where-a-test-stopped" tabindex="-1">Where a test stopped <a class="header-anchor" href="#where-a-test-stopped" aria-label="Permalink to &quot;Where a test stopped&quot;">​</a></h2><p>A test of a run on your machine stops at a call and waits to be answered: at a breakpoint, after a step, at a Pause, at the line it was run to, at <code>page.pause()</code>, or at a failure <a href="#hold-failures">held</a> for a look. Every tool says why in the same words:</p><ul><li><strong>Stopped at a breakpoint</strong>, <strong>Stopped after a step</strong>, <strong>Paused</strong>, <strong>Stopped at the line it ran to</strong>, <strong>Stopped at page.pause()</strong>, and <strong>Stopped</strong> for a reason a newer reporter names;</li><li><strong>Held at its failure</strong>, then how the test failed (<strong>Failed at</strong> and its place in the Runs window and the desktop app&#39;s tray);</li><li>at a stop an agent asked for, <strong>Paused by the agent</strong>, <strong>Stopped after the agent&#39;s step</strong> or <strong>Stopped at the line the agent ran it to</strong>.</li></ul><p>The editors show it above the stopped line, the Runs window and the desktop app&#39;s tray on the worker, and the terminal on a line naming the editor, or the desktop app, that steers the run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[piwi] Stopped at a breakpoint at tests/cart.spec.ts:12 before Click: Resume, Step or Finish in Visual Studio Code.</span></span></code></pre></div><p>Edit the file at a stop, and the Runs window names the stopped line where it stands now, as the editor does.</p><p><strong>On the run&#39;s page</strong>, the test&#39;s row says why, at the stopped call, whose place opens in your editor. A shared run tells it from its <a href="./live-view.html">live view</a>; a run nobody shares, as text with <code>@piwitests/reporter</code> 0.68.0 or later: the call&#39;s title, its file and line, the test&#39;s title and since when, as each stop shows and ends, never an image, the row saying for how long once it has stood a minute. A stopped test is never marked <a href="./stuck-tests.html"><strong>Stuck?</strong></a>.</p><p>At a stop of a headed run, every tool offers <strong>Show the browser</strong>, which brings the test&#39;s window to the front where your system allows: <strong>Piwi: Show the stopped test&#39;s browser</strong> in VS Code and the stop&#39;s hover, <strong>Tools → Piwi → Show the stopped test&#39;s browser</strong> in a JetBrains IDE, and a button in the Runs window and the desktop app&#39;s tray. A headless run has none to show, nor does an older reporter.</p><h3 id="hold-failures" tabindex="-1">Hold failures <a class="header-anchor" href="#hold-failures" aria-label="Permalink to &quot;Hold failures&quot;">​</a></h3><p><strong>Hold failures</strong> decides, for one run, whether a failing test waits at its line. Held, the test keeps its page once its function, hooks and fixtures are done, at the line where the error entered its code, else the failing locator&#39;s, else the call a test timeout cut short. <strong>Resume</strong>, <strong>Step</strong> and <strong>Finish</strong> let it end as it failed; <strong>Pick</strong> and <strong>Record</strong> fix it there (<a href="./editor-stop-code.html#a-failure">Code from a pause</a>). Each failing attempt is held once, an expected failure never. Piwi&#39;s evidence is the page at the failure: the requests, console entries and dialogs of the hold are not recorded, while Playwright&#39;s trace and video go on.</p><p>Headed or headless, it is off unless turned on; off, a failure goes on at once, as without Piwi:</p><ul><li><strong>From the run&#39;s start</strong> in a run with the editor&#39;s breakpoints or a spec&#39;s <code>page.pause()</code>, a <a href="./debug-in-editor.html">debug run</a>, a desktop app&#39;s reproduction, a run an agent starts (<code>run_start</code>, until two minutes after its last call), or one whose start options choose it (<a href="./editor-runs.html#how-a-run-starts">editor</a>, <a href="./desktop-runs.html#each-worker">desktop app</a>).</li><li><strong>While it runs</strong>, from any tool that follows it: the editors (<strong>Piwi: Turn hold failures on or off for the run</strong>, <strong>Tools → Piwi → Turn hold failures on</strong> or <strong>off</strong>), the switch on each run of the Runs window, the desktop app&#39;s tray and Piwi Runner, or an agent (<code>run_follow</code>). Each tool shows it as the last one set it. Turned off, a held failure no pause bar shows goes on.</li><li><strong>Never</strong> in a run nobody attends: a Flake Lab run, a bisect, a lab job, <strong>Verify ×3</strong>, a fix plan&#39;s verification, a Flake Lab line, a terminal run whose output goes to a file or a pipe, <code>--repeat-each</code> above 1 without <code>--max-failures=1</code>, and UI mode. Their switch says why.</li></ul><p>A run <a href="./terminal-runs.html">started in a terminal</a> holds a failure only once you turn it on, and a held failure goes on once no tool is left to show it.</p><h2 id="share-with-playwright-tools" tabindex="-1">Share with Playwright tools <a class="header-anchor" href="#share-with-playwright-tools" aria-label="Permalink to &quot;Share with Playwright tools&quot;">​</a></h2><p>At a stop, <strong>Share with Playwright tools</strong> binds the test&#39;s browser for Playwright&#39;s own tools: <a href="./editor-run-control.html#share-with-playwright-tools">Pause and step from the editor</a>.</p><h2 id="the-terminal-s-lines" tabindex="-1">The terminal&#39;s lines <a class="header-anchor" href="#the-terminal-s-lines" aria-label="Permalink to &quot;The terminal&#39;s lines&quot;">​</a></h2><p>What a run prints in its terminal (its page, the editor or the desktop app it follows, its progress): <a href="./terminal-runs.html#the-terminal-s-lines">Runs started outside Piwi</a>.</p><h2 id="when-the-run-does-not-reach-the-instance" tabindex="-1">When the run does not reach the instance <a class="header-anchor" href="#when-the-run-does-not-reach-the-instance" aria-label="Permalink to &quot;When the run does not reach the instance&quot;">​</a></h2><p>What the editor says of a run it started that sent nothing: <a href="./editor-runs.html#after-a-run">Runs from the editor</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./watch-running-test.html">Watch a local test</a>: a test&#39;s page, in your tools</li><li><a href="./live-view.html">Live view of a run</a>: a test&#39;s page, on the team instance</li><li><a href="./share-live.html">Share a local run live</a>: a teammate watches a run on your machine</li><li><a href="./runs-window.html">Runs window</a>: follow and steer your runs from Piwi Picker</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls at a stop</li></ul>',31))])}const y=o(l,[["render",p]]);export{b as __pageData,y as default};
